.hero{position: relative; min-height: 100svh; background: var(--bg); overflow: hidden;}
.hero-grid{position: relative; z-index: 4; width: min(1600px, 100% - 32px); margin: 0px auto; min-height: 100svh; display: grid; grid-template-columns: 0.4fr 0.6fr; gap: 0px; padding-top: 110px;}
.hero-copy{position: relative; z-index: 30; display: flex; align-items: center; justify-content: center; padding: 56px 22px 56px 0px;}
.hero-copy-inner{width: 100%; max-width: 560px; padding: 28px 28px 32px; background: rgba(14, 14, 14, 0.44); border: 1px solid rgba(255, 255, 255, 0.08); backdrop-filter: blur(20px) contrast(0.95); box-shadow: rgba(255, 255, 255, 0.08) 0px 1px 0px inset, rgba(0, 0, 0, 0.38) 0px 24px 60px;}
.hero-kicker{display: inline-flex; align-items: center; gap: 10px; padding: 10px 14px; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.08); text-transform: uppercase; letter-spacing: 0.28em; font-size: 10px; color: rgba(255, 255, 255, 0.7);}
.hero-kicker span{width: 8px; height: 8px; background: var(--ochre); display: inline-block;}
.hero-title{margin-top: 22px; font-size: clamp(4.2rem, 10vw, 8.6rem); line-height: 0.82; letter-spacing: -0.08em; color: white; text-shadow: rgba(0, 0, 0, 0.22) 0px 8px 20px, rgba(235, 170, 84, 0.06) 0px 0px 20px;}
.heat-wave{display: inline-block; animation: 6.5s ease-in-out 0s infinite normal none running heatWave; transform-origin: left center;}
.hero-text{margin-top: 20px; color: rgba(255, 255, 255, 0.82); font-family: "PP Neue Montreal", "Inter Tight", sans-serif; line-height: 1.95; font-size: 16px;}
.specs{margin-top: 22px; display: flex; flex-wrap: wrap; gap: 10px;}
.specs span{padding: 10px 12px; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.08); text-transform: uppercase; letter-spacing: 0.2em; font-size: 10px; color: rgba(255, 255, 255, 0.72);}
.hero-cta{display: flex; gap: 12px; flex-wrap: wrap; margin-top: 26px;}
.hero-cta button{height: 54px; padding: 0px 20px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; cursor: pointer; font-size: 10px; letter-spacing: 0.28em; text-transform: uppercase;}
.hero-visual{position: relative; min-height: 100svh; overflow: hidden; z-index: 10;}
.splash-shell{position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 120%; height: 110%; display: flex; align-items: center; justify-content: center;}
.splash-shell video{width: 100%; height: 100%; object-fit: contain; object-position: center center;}
.sauce-glow{position: absolute; inset: 0px; background: radial-gradient(circle at 18% 26%, rgba(0, 0, 0, 0.28), transparent 18%), radial-gradient(circle at 52% 24%, rgba(255, 228, 195, 0.12), transparent 16%), radial-gradient(circle at 70% 62%, rgba(110, 208, 76, 0.16), transparent 16%), linear-gradient(rgba(0, 37, 32, 0.08), rgba(0, 0, 0, 0.4)); pointer-events: none;}
.ingredient-field{position: absolute; inset: 0px; z-index: 22; pointer-events: none; overflow: hidden;}
.seed, .drip{position: absolute; background: rgba(255, 242, 216, 0.9); transform-origin: center center; filter: drop-shadow(rgba(255, 193, 85, 0.12) 0px 0px 8px); animation: 10s linear 0s infinite normal none running flight;}
.seed{width: 10px; height: 4px; border-radius: 2px;}
.drip{width: 18px; height: 6px; border-radius: 2px; background: rgba(255, 126, 40, 0.9);}
.heat-scrim{position: absolute; left: 0px; top: 0px; bottom: 0px; width: 42%; z-index: 28; background: linear-gradient(90deg, rgba(12, 12, 12, 0.64), rgba(12, 12, 12, 0.32) 55%, transparent 100%); pointer-events: none;}
.reveal{opacity: 0; transform: translateY(28px); transition: opacity 0.8s, transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);}
.reveal.in{opacity: 1; transform: translateY(0px);}
