@media (max-width: 1180px){.foot-grid{align-items: flex-start;}}
@media (max-width: 760px){.shell, .finish-shell, .foot-shell{width: min(100% - 20px, 1600px);}}
@media (max-width: 760px){.menu-board{padding: 24px;}}
h2, h3{font-size: inherit; font-weight: inherit;}
button{font-family: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-size: 100%; font-weight: inherit; line-height: inherit; letter-spacing: inherit; color: inherit; margin: 0px; padding: 0px;}
button{text-transform: none;}
button{appearance: button; background-color: transparent; background-image: none;}
h2, h3, p{margin: 0px;}
button{cursor: pointer;}
.mt-5{margin-top: 1.25rem;}
.h-\[54px\]{height: 54px;}
.px-5{padding-left: 1.25rem; padding-right: 1.25rem;}
.text-\[10px\]{font-size: 10px;}
.uppercase{text-transform: uppercase;}
.tracking-\[0\.34em\]{letter-spacing: 0.34em;}
.text-white{--tw-text-opacity: 1; color: rgb(255 255 255 / var(--tw-text-opacity, 1));}
